// Armamos un cuerpo multipart/form-data a mano y lo volvemos a partir, como hace un servidor.
function armar(partes, borde) {
  let cuerpo = "";
  for (const p of partes) {
    cuerpo += `--${borde}\r\nContent-Disposition: form-data; name="${p.campo}"` + (p.archivo ? `; filename="${p.archivo}"` : "") + "\r\n";
    if (p.tipo) cuerpo += `Content-Type: ${p.tipo}\r\n`;
    cuerpo += `\r\n${p.contenido}\r\n`;
  }
  return cuerpo + `--${borde}--\r\n`;
}
function partir(cuerpo, borde) {
  const trozos = cuerpo.split(`--${borde}`).slice(1, -1); // lo que hay entre separadores
  return trozos.map((t) => {
    const [cabecera, ...resto] = t.slice(2).split("\r\n\r\n");
    return { cabecera: cabecera.replace(/\r\n/g, " | "), contenido: resto.join("\r\n\r\n").replace(/\r\n$/, "") };
  });
}

