const firmar = (metodo, ruta, expira) =>
  crypto.createHmac("sha256", SECRETO).update(`${metodo}\n${ruta}\n${expira}`).digest("hex");

function verificarFirma(metodo, url) {
  const expira = Number(url.searchParams.get("expira"));
  const firma = url.searchParams.get("firma") || "";
  const a = Buffer.from(firma, "hex");
  const b = Buffer.from(firmar(metodo, url.pathname, expira), "hex");
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return "firma inválida";
  if (Date.now() / 1000 > expira) return "firma vencida";
  return null; // todo en orden
}

const r = /^bytes=(\d*)-(\d*)$/.exec(req.headers["range"] || "");
if (r) {
  if (r[1] === "") inicio = Math.max(0, total - Number(r[2]));           // bytes=-50: los últimos 50
  else { inicio = Number(r[1]); if (r[2] !== "") fin = Math.min(Number(r[2]), total - 1); }
  if (inicio > fin || inicio >= total) {                                  // pide más allá del final
    res.writeHead(416, { "content-range": `bytes */${total}` }); return res.end();
  }
  estado = 206; cab["content-range"] = `bytes ${inicio}-${fin}/${total}`;
}
